    unit_price DECIMAL(10,2) NOT NULL,
    discount DECIMAL(4,2) NOT NULL,
    CONSTRAINT pk_order_items PRIMARY KEY (order_item_id),
    CONSTRAINT fk_order_items_order_id FOREIGN KEY (order_id) REFERENCES dbo.orders (order_id),
